"use client";
// Cyrus mega staging UI (CYRUS_MEGA_STAGING): the "Build this in stages" card on the plan screen and the chain panel on the
// project page. Every stage is the normal change build (POST /api/mod-builder/builds with baseBuildId + changeRequest), so
// holds, gates, the ledger and Test Flight behave exactly as for any refine. "Run all stages" chains them and STOPS on a
// failed stage; nothing is started after it and nothing more is held. lib/cyrus/planner/mega.ts has the logic and the tests.
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { nextStep, stageBuildBody, STAGE_TEXT_MAX, type ChainStage, type StageChain } from "@/lib/cyrus/planner/mega";
import type { MegaPlan } from "@/lib/cyrus/planner/run";

const n = (x: number) => Math.round(x).toLocaleString("en-US");

export type StagePick = { stages: ChainStage[]; auto: boolean };

/** The plan card for a mega request: ordered, editable stage list, estimate per stage, one click to start (or run all). */
export function StagePlanCard({ mega, busy, onStart }: { mega: MegaPlan; busy: boolean; onStart: (p: StagePick) => void }) {
  const [texts, setTexts] = useState<Record<string, string>>({});
  const [off, setOff] = useState<Record<string, boolean>>({});
  const stages = mega.stages.filter((s) => !off[s.id]);
  const pick = (auto: boolean) => onStart({ auto, stages: stages.map((s) => ({ id: s.id, title: s.title, text: (texts[s.id] ?? s.text).slice(0, s.kind === "core" ? 4000 : STAGE_TEXT_MAX) })) });
  if (!mega.staged) return null;
  return (
    <div className="cx-list" data-testid="mega-stages" aria-label="Build this in stages" style={{ display: "grid", gap: 8 }}>
      <b style={{ fontSize: 14 }}>This is a very large request. Build it in stages?</b>
      <span className="cx-muted" style={{ fontSize: 13 }}>
        {mega.reason}. One build of everything can run out of time with nothing delivered; stages are smaller, each is tested, and each keeps everything the stage before it made.
      </span>
      <ol style={{ display: "grid", gap: 8, margin: 0, paddingLeft: 18 }}>
        {mega.stages.map((s, i) => (
          <li key={s.id} style={{ opacity: off[s.id] ? 0.5 : 1 }}>
            <div style={{ display: "flex", gap: 8, alignItems: "baseline", flexWrap: "wrap" }}>
              <b>{s.title}</b>
              {s.cost ? <span className="cx-faint" style={{ fontSize: 12 }}>{s.cost.minutes[0]}-{s.cost.minutes[1]} min{s.cost.tokens ? ` · ${n(s.cost.tokens[0])}-${n(s.cost.tokens[1])} tokens` : ""}</span> : null}
              {s.large ? <span className="cx-faint" style={{ fontSize: 12, color: "var(--cx-warn)" }}>still large: consider trimming it</span> : null}
              {i > 0 ? <button type="button" className="cx-btn cx-btn-sm" onClick={() => setOff((o) => ({ ...o, [s.id]: !o[s.id] }))}>{off[s.id] ? "Include" : "Skip for now"}</button> : null}
            </div>
            <textarea
              className="cx-input" rows={3} value={texts[s.id] ?? s.text} disabled={!!off[s.id]} aria-label={`${s.title} request`}
              onChange={(e) => setTexts((t) => ({ ...t, [s.id]: e.target.value.slice(0, s.kind === "core" ? 4000 : STAGE_TEXT_MAX) }))}
              style={{ width: "100%", fontSize: 13 }}
            />
          </li>
        ))}
      </ol>
      <div className="cx-muted" style={{ fontSize: 13 }}>
        All stages together: about {mega.total.minutes[0]}-{mega.total.minutes[1]} min{mega.total.tokens ? ` · ${n(mega.total.tokens[0])}-${n(mega.total.tokens[1])} tokens` : ""}
        {mega.dailyCap && mega.total.tokens && mega.total.tokens[1] > mega.dailyCap ? ` (more than one day's limit of ${n(mega.dailyCap)}: run them over two days)` : ""}.
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <button type="button" className="cx-btn cx-btn-energy" disabled={busy || !stages.length} onClick={() => pick(false)}>Build stage 1 now</button>
        <button type="button" className="cx-btn" disabled={busy || stages.length < 2} onClick={() => pick(true)} title="Starts stage 1, then each next stage when the one before it passes. Stops at the first stage that fails.">Run all {stages.length} stages</button>
      </div>
    </div>
  );
}

/** Project page: where the chain stands, and the buttons to continue (or the automatic continuation when "run all" was chosen). */
export function StageChainPanel({ chain, buildId, status }: { chain: StageChain; buildId: string; status: string }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [auto, setAuto] = useState(chain.auto === true);
  const started = useRef<string | null>(null);
  const step = nextStep(chain, status);

  const run = async (asAuto: boolean) => {
    if (step.action !== "run" || busy) return;
    setBusy(true); setErr(null);
    const body = stageBuildBody({ ...chain, auto: asAuto }, buildId, { model: "auto" });
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
      const j = (await r.json().catch(() => ({}))) as { build?: { id: string; rootBuildId: string | null }; error?: string };
      if (r.status === 201 && j.build) { router.refresh(); return; }
      setErr(j.error || `Could not start the next stage (${r.status}). The stages after it were not started.`);
      setAuto(false);
    } catch { setErr("Network problem: the next stage was not started."); setAuto(false); }
    setBusy(false);
  };

  // "Run all": continue automatically once, per finished build (the ref keeps a re-render from posting twice).
  useEffect(() => {
    if (!auto || step.action !== "run" || started.current === buildId) return;
    started.current = buildId;
    void run(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [auto, buildId, status]);

  const label = (i: number) => (i < chain.index ? "done" : i === chain.index ? (status === "succeeded" ? "done" : status === "failed" ? "failed" : "building") : "waiting");
  return (
    <div data-testid="stage-chain" style={{ display: "grid", gap: 8 }}>
      <b>Staged build: stage {chain.index + 1} of {chain.stages.length}</b>
      <ol style={{ margin: 0, paddingLeft: 18, display: "grid", gap: 4, fontSize: 13 }}>
        {chain.stages.map((s, i) => <li key={s.id}><b>{s.title}</b> <span className="cx-faint">{label(i)}</span></li>)}
      </ol>
      {step.action === "stop" ? <p role="alert" style={{ margin: 0, color: "var(--cx-warn)", fontSize: 13 }}>{step.reason}</p> : null}
      {step.action === "done" ? <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>All stages are built.</p> : null}
      {step.action === "run" ? (
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button type="button" className="cx-btn cx-btn-energy" disabled={busy} onClick={() => void run(false)}>{busy ? "Starting…" : `Build stage ${step.index + 1}: ${step.stage.title}`}</button>
          {chain.stages.length - step.index > 1 ? <button type="button" className="cx-btn" disabled={busy} onClick={() => { setAuto(true); started.current = null; void run(true); }}>Run all remaining stages</button> : null}
        </div>
      ) : null}
      {err ? <p className="cx-error" role="alert" style={{ margin: 0 }}>{err}</p> : null}
    </div>
  );
}

