describe("prompt coach: archetypes", () => {
  it("every coverage-matrix archetype has a coach template and every template is in the matrix", () => {
    const tpl = new Set(COACH_TEMPLATES.map((t) => t.id));
    assert.ok(COVERAGE_ARCHETYPE_IDS.length >= 90, `${COVERAGE_ARCHETYPE_IDS.length}`);
    assert.deepEqual(COVERAGE_ARCHETYPE_IDS.filter((a) => !tpl.has(a)), [], "matrix archetypes without a coach template");
    assert.deepEqual([...tpl].filter((a) => !COVERAGE_ARCHETYPE_IDS.includes(a)), [], "coach templates not in the matrix");
    for (const t of COACH_TEMPLATES) for (const d of t.dims) assert.ok(GAP_IDS.includes(d), `${t.id}: ${d}`);
  });
  it("recognises the archetype of the coverage eval prompts (>= 90% top-1)", () => {
    const set = read("services/modbuilder/eval/sets/coverage.jsonl").split("\n").filter(Boolean).map((l) => JSON.parse(l) as { prompt: string; archetype?: string }).filter((p) => p.archetype);
    assert.ok(set.length >= 80, `${set.length}`);
    const hit = set.filter((p) => matchArchetype(p.prompt)?.id === p.archetype).length;
    assert.ok(hit / set.length >= 0.9, `${hit}/${set.length}`);
  });
  it("archetype facts give limits and per-version lines from the matrix", () => {
    const d = archetypeFacts("dialog_forms", "1.21.4")!;
    assert.equal(d.status, "partial");
    assert.ok(d.versionLines.some((l) => l.includes("no Dialog API")));
    assert.deepEqual(archetypeFacts("dialog_forms", "1.21.11")!.versionLines, []);
    assert.equal(archetypeFacts("nope", V), null);
  });
});

describe("prompt coach: guard-trigger phrasing", () => {
  it("flags instruction-like phrasing and suggests describing the mod", () => {
Minecraft coverage matrix (bundle mc-coverage): which Cyrus lane serves each kind of mod people ask for, how well, per-version availability and the limits the planner must tell the user BEFORE credits are spent. Lane names = lib/cyrus/planner/lanes.ts LANES plus 'plugin' (the Paper plugin every build has). Per-version entries are {lane, availability: available|limited|unavailable, reason, substitu
1
['plugin', 'texture', 'itemStates', 'sound', 'model3d', 'creature', 'designItem', 'designMenu', 'designQuest', 'designBoss', 'designHud', 'motion', 'config', 'datapack', 'worldgen', 'library']
['assets', 'audio', 'blocks', 'chat', 'client', 'commands', 'cosmetics', 'display', 'economy', 'equipment', 'game-mechanics', 'gui', 'hud', 'integration', 'items', 'library', 'management', 'minigames', 'mobs', 'moderation', 'optimization', 'permissions', 'progression', 'protection', 'pvp', 'rewards', 'social', 'technology', 'teleport', 'utility', 'visuals', 'world']

// Cyrus PROMPT COACH: deterministic prompt-quality analysis (pure TypeScript, NO model call, zero cost, unit-tested in
// test/cyrus-coach.test.ts). Runs on the plan screen BEFORE anything is held. It answers: for THIS kind of request
// (archetype of the coverage matrix + what the words imply: heavy work, world changes, saved state, things it creates),
// on THIS game/version, which details are missing that a builder needs to get it right the first time:
//   trigger / when, exact numbers and limits, worlds/dimensions, scope (what must stay unchanged on a change request),
//   persistence and config wishes, commands and permissions, performance bounds, edge cases and what must NOT happen,
//   anti-abuse, modes, player feedback, version.
// It also flags phrasing the Haiku intake guard misreads (instructions to the AI, "keep everything exactly as is",
// unbounded or crash/lag wording, hidden privileges) and suggests describing the mod instead (2026-10-12 false refusal,
// fix/cyrus-guard-change-requests 4a2a5b3d2e), and collects the honest capability lines the user should see before spend.
// Output: { score 0-100, level great|good|vague, gaps [{id, question, why, example, input}], strengths, ... }.
import { ruleNeeds } from "../planner/rules";
import { LANE_META, type Lane } from "../planner/lanes";
import type { PlannedLane } from "../planner/decide";
import { GAP_IDS, TECHNIQUE_ARCHETYPES, TEMPLATE_BY_ID, matchArchetype, type CoachField, type CoachTemplate, type GapId } from "./archetypes";
import { archetypeFacts } from "./catalogue";

export const COACH_REPORT_VERSION = 1;
export type CoachLevel = "great" | "good" | "vague";

export type CoachInputSpec =
  | { kind: "chips"; options: string[]; multi: boolean; defaults: string[]; extra?: string }
  | { kind: "fields"; fields: CoachField[] }
  | { kind: "text"; placeholder: string; def: string };

export type CoachGap = { id: GapId; question: string; why: string; example: string; input: CoachInputSpec; weight: number; partial?: boolean };
export type GuardRisk = { id: string; phrase: string; why: string; suggestion: string; /** an instruction-like sentence the compiler leaves out */ drop: boolean };
export type ChangeContext = { name: string; version?: number; summary?: string | null; paths?: string[] };
export type CoachReport = {
  v: typeof COACH_REPORT_VERSION;
  score: number;
  level: CoachLevel;
  kind: "new" | "change";
  version: string;
  archetype: { id: string; label: string; status: string } | null;
  /** Every missing detail, most important first. */
  gaps: CoachGap[];
  /** The 3-6 questions the panel asks (a subset of gaps). */
  questions: CoachGap[];
  strengths: string[];
  guardRisks: GuardRisk[];
  /** Honest limits for this request on this game/version (archetype, version, platform, planned lanes). */
  capability: string[];
  /** Change requests only: what the change keeps, and planned lanes the text does not ask for. */
  change: { target: string; kept: string[]; unasked: { lane: Lane; label: string }[]; held: { lane: Lane; label: string }[] } | null;
  /** A name for the mod when the text gives one ("called X", "a chunk mirror mod"). */
  name: string | null;
  words: number;
};

export type CoachInput = {
  text: string;
  version: string;
  game?: string;
  change?: ChangeContext | null;
  /** The plan screen's lanes (lib/cyrus/planner/decide.ts), for capability lines and the change-lane check. */
  lanes?: Pick<PlannedLane, "lane" | "state" | "label" | "warning" | "capability">[] | null;
  /** Lanes the plan screen kept out of a change because its text does not ask for them (./plan-hook.ts). */
  held?: Lane[] | null;
  /** The technique switch (CYRUS_MC_TECHNIQUES: vein miners, mob catchers). false = say they are not available yet; undefined = unknown (the matrix limits apply). */
  techniques?: boolean;
};

// ---------- word rules (what a prompt already says) ----------
