function limitFields(c: Ctx): CoachField[] {
  const out: CoachField[] = [];
  if (c.kinds.mob) out.push({ key: "mobsTotal", label: "Max alive at once", def: "200" });
  if (c.kinds.heavy) out.push({ key: "perAction", label: "Max changes per action", def: "100" });
