package dev.nxeon.golden.dungeon;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.bossbar.BossBar;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.title.Title;
import org.bukkit.Bukkit;
import org.bukkit.GameMode;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.World;
import org.bukkit.WorldCreator;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.CreatureSpawnEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerRespawnEvent;
import org.bukkit.generator.ChunkGenerator;
import org.bukkit.generator.WorldInfo;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.potion.PotionEffect;
import org.bukkit.scheduler.BukkitTask;

/**
 * Golden "instanced dungeon lite": /dungeon start makes a private EMPTY (void) world for the run, saves the player's own
 * state (location, inventory, game mode, health, food, level, effects) to a file, and puts them in a small stone room.
 * The server's own worlds are never touched. /dungeon leave|abandon, death, disconnect and a crash (restored on the next
 * join) all give the player back exactly what they had, then the run world is unloaded and its folder deleted.
 * Rooms are built a few blocks per tick, there is one repeating task for all runs, the floor counter lives in the
 * player's persistent data (per player, survives restarts) and the HUD is a boss bar plus a title on a new floor.
 */
public class Dungeon extends JavaPlugin implements Listener {
    static final String PREFIX = "nxdungeon_";
    static final int HALF = 3;            // room is (2*HALF+1) square
    static final int FLOOR_Y = 64;
    static final int DOOR_Z = -HALF;      // the north wall
    private NamespacedKey bestKey;
    private final Map<UUID, Run> runs = new HashMap<>();
    private BukkitTask loop;
    private File stateDir;

    /** Empty world: a ChunkGenerator that overrides nothing generates void chunks and no structures. */
    static final class VoidGenerator extends ChunkGenerator {
        @Override
        public Location getFixedSpawnLocation(WorldInfo info, Random random) { return null; }
    }

    static final class Run {
        final UUID player;
        final String worldName;
        World world;
        int floor = 1;
        boolean combat = true;
        boolean ready;                       // room built and mobs spawned
        boolean open;                        // door open
        final Set<UUID> mobs = new HashSet<>();
        final ArrayDeque<int[]> pending = new ArrayDeque<>();   // x, y, z, material ordinal
        BossBar bar;
        Run(UUID player, String worldName) { this.player = player; this.worldName = worldName; }
    }

    @Override
    public void onEnable() {
        saveDefaultConfig();
        bestKey = new NamespacedKey(this, "best_floor");
        stateDir = new File(getDataFolder(), "saved");
        stateDir.mkdirs();
        getCommand("dungeon").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        loop = getServer().getScheduler().runTaskTimer(this, this::tick, 10L, 2L);
        // leftovers of a crashed run: delete the run worlds' folders (they are not loaded; players are restored on join)
        getServer().getScheduler().runTaskAsynchronously(this, () -> {
            File[] dirs = getServer().getWorldContainer().listFiles();
            if (dirs == null) return;
            for (File d : dirs) if (d.isDirectory() && d.getName().startsWith(PREFIX) && getServer().getWorld(d.getName()) == null) deleteTree(d.toPath());
        });
    }

    @Override
    public void onDisable() {
        if (loop != null) loop.cancel();
        for (Run r : new ArrayList<>(runs.values())) {
            Player p = getServer().getPlayer(r.player);
            if (p != null) restoreNow(p);
            dispose(r);
        }
        runs.clear();
    }

    // ------------------------------------------------------------------ commands
    @Override
    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage("Players only."); return true; }
        String sub = args.length > 0 ? args[0].toLowerCase() : "status";
        switch (sub) {
            case "start" -> start(p);
            case "leave", "abandon" -> {
                Run r = runs.get(p.getUniqueId());
                if (r == null) { p.sendMessage(Component.text("You are not in a run.", NamedTextColor.RED)); return true; }
                finish(p, "You left the dungeon on floor " + r.floor + ".");
            }
            default -> {
                Run r = runs.get(p.getUniqueId());
                int best = p.getPersistentDataContainer().getOrDefault(bestKey, PersistentDataType.INTEGER, 0);
                p.sendMessage(r == null ? "Dungeon: no active run, best floor " + best + "." : "Dungeon: floor " + r.floor + " / " + max() + ", best floor " + best + ".");
            }
        }
        return true;
    }

    private int max() { return Math.max(1, getConfig().getInt("max-floors", 100)); }

    private void start(Player p) {
        if (runs.containsKey(p.getUniqueId())) { p.sendMessage(Component.text("You are already in a run.", NamedTextColor.RED)); return; }
        if (stateFile(p.getUniqueId()).exists()) { p.sendMessage(Component.text("Your previous run is still being put back. Try again in a moment.", NamedTextColor.RED)); return; }
        String name = PREFIX + p.getUniqueId().toString().substring(0, 8);
        World w = getServer().getWorld(name);
        if (w == null) w = new WorldCreator(name).generator(new VoidGenerator()).generateStructures(false).createWorld();
        if (w == null) { p.sendMessage(Component.text("Could not create the dungeon world.", NamedTextColor.RED)); return; }
        w.setAutoSave(false);
        saveState(p);                                           // BEFORE anything changes
        Run r = new Run(p.getUniqueId(), name);
        r.world = w;
        runs.put(p.getUniqueId(), r);
        p.getInventory().clear();
        for (PotionEffect e : p.getActivePotionEffects()) p.removePotionEffect(e.getType());
        p.setGameMode(GameMode.SURVIVAL);
        p.setFoodLevel(20);
        queueShell(r);
        r.bar = BossBar.bossBar(Component.text("Floor 1 / " + max()), 0f, BossBar.Color.RED, BossBar.Overlay.PROGRESS);
        p.showBossBar(r.bar);
        enterFloor(p, r);
    }

    // ------------------------------------------------------------------ the room (built a few blocks per tick)
    private void queueShell(Run r) {
        for (int x = -HALF; x <= HALF; x++) for (int z = -HALF; z <= HALF; z++) {
            r.pending.add(new int[] { x, FLOOR_Y - 1, z, Material.STONE_BRICKS.ordinal() });
            boolean edge = Math.abs(x) == HALF || Math.abs(z) == HALF;
            for (int y = FLOOR_Y; y < FLOOR_Y + 3; y++) {
                if (edge) r.pending.add(new int[] { x, y, z, (z == DOOR_Z && x == 0 && y < FLOOR_Y + 2 ? Material.IRON_BARS : Material.STONE_BRICKS).ordinal() });
            }
        }
    }

    private void tick() {
        int perTick = Math.max(8, Math.min(256, getConfig().getInt("blocks-per-tick", 64)));
        for (Run r : new ArrayList<>(runs.values())) {
            Player p = getServer().getPlayer(r.player);
            if (p == null) continue;
            if (!r.pending.isEmpty()) {
                Material[] mats = Material.values();
                for (int i = 0; i < perTick && !r.pending.isEmpty(); i++) {
                    int[] b = r.pending.poll();
                    r.world.getBlockAt(b[0], b[1], b[2]).setType(mats[b[3]], false);
                }
                continue;
            }
            if (!r.ready) { r.ready = true; populate(p, r); }
            if (!r.open && r.combat && r.mobs.isEmpty()) openDoor(p, r);
            // through the open door = next floor
            if (r.open && p.getWorld().equals(r.world) && p.getLocation().getZ() < DOOR_Z - 0.5) nextFloor(p, r);
        }
    }

    private void enterFloor(Player p, Run r) {
        r.ready = false;
        r.open = false;
        r.mobs.clear();
        r.combat = r.floor % Math.max(1, getConfig().getInt("treasure-every", 5)) != 0;
        r.bar.name(Component.text("Floor " + r.floor + " / " + max() + " - " + (r.combat ? "combat room" : "treasure room")));
        r.bar.progress(Math.min(1f, (float) r.floor / max()));
        p.showTitle(Title.title(Component.text("Floor " + r.floor), Component.text(r.combat ? "Clear the room" : "Take the reward")));
        closeDoor(r);
        Location in = new Location(r.world, 0.5, FLOOR_Y, HALF - 0.5, 180f, 0f);
        safeTeleport(p, in, null);
    }

    private void populate(Player p, Run r) {
        if (r.combat) {
            int n = Math.min(Math.max(1, getConfig().getInt("max-mobs", 8)), getConfig().getInt("mobs-base", 2) + r.floor / 5);
            for (int i = 0; i < n; i++) {
                Location at = new Location(r.world, -HALF + 1.5 + (i % (2 * HALF - 1)), FLOOR_Y, -1.5 + (i / (2 * HALF - 1)));
                var e = r.world.spawnEntity(at, EntityType.ZOMBIE);
                if (e instanceof LivingEntity le) le.setRemoveWhenFarAway(false);
                r.mobs.add(e.getUniqueId());
            }
        } else {
            r.world.getBlockAt(0, FLOOR_Y, 0).setType(Material.CHEST, false);
            if (r.world.getBlockAt(0, FLOOR_Y, 0).getState() instanceof org.bukkit.block.Chest c) c.getBlockInventory().addItem(new ItemStack(Material.BREAD, 2 + r.floor / 5));
            openDoor(p, r);
        }
    }

    private void closeDoor(Run r) {
        for (int y = FLOOR_Y; y < FLOOR_Y + 2; y++) r.world.getBlockAt(0, y, DOOR_Z).setType(Material.IRON_BARS, false);
        r.world.getBlockAt(0, FLOOR_Y, 0).setType(Material.AIR, false);
    }

    private void openDoor(Player p, Run r) {
        r.open = true;
        for (int y = FLOOR_Y; y < FLOOR_Y + 2; y++) r.world.getBlockAt(0, y, DOOR_Z).setType(Material.AIR, false);
        p.sendActionBar(Component.text("The door is open", NamedTextColor.GREEN));
    }

    private void nextFloor(Player p, Run r) {
        if (r.floor >= max()) { recordBest(p, r.floor); finish(p, "You cleared all " + max() + " floors."); return; }
        r.floor++;
        recordBest(p, r.floor);
        enterFloor(p, r);
    }

    private void recordBest(Player p, int floor) {
        var pdc = p.getPersistentDataContainer();
        if (floor > pdc.getOrDefault(bestKey, PersistentDataType.INTEGER, 0)) pdc.set(bestKey, PersistentDataType.INTEGER, floor);
    }

    // ------------------------------------------------------------------ events
    @EventHandler
    public void onMobDeath(EntityDeathEvent e) {
        for (Run r : runs.values()) if (r.mobs.remove(e.getEntity().getUniqueId())) e.getDrops().clear();
    }

    @EventHandler
    public void onSpawn(CreatureSpawnEvent e) {
        if (e.getLocation().getWorld() != null && e.getLocation().getWorld().getName().startsWith(PREFIX) && e.getSpawnReason() != CreatureSpawnEvent.SpawnReason.CUSTOM) e.setCancelled(true);
    }

    @EventHandler
    public void onDeath(PlayerDeathEvent e) {
        if (!runs.containsKey(e.getEntity().getUniqueId())) return;
        e.setKeepInventory(true);
        e.setKeepLevel(true);
        e.getDrops().clear();
        e.setShouldDropExperience(false);
    }

    @EventHandler(priority = EventPriority.HIGHEST)
    public void onRespawn(PlayerRespawnEvent e) {
        Player p = e.getPlayer();
        if (!runs.containsKey(p.getUniqueId())) return;
        File f = stateFile(p.getUniqueId());
        if (f.exists()) {
            Location back = YamlConfiguration.loadConfiguration(f).getLocation("location");
            if (back != null && back.getWorld() != null) e.setRespawnLocation(back);
        }
        getServer().getScheduler().runTask(this, () -> { if (p.isOnline()) finish(p, "You died. Everything you had before the run is back."); });
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        Run r = runs.remove(e.getPlayer().getUniqueId());
        if (r == null) return;
        restoreNow(e.getPlayer());
        dispose(r);
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();
        if (runs.containsKey(p.getUniqueId()) || !stateFile(p.getUniqueId()).exists()) return;
        // a crash (or a kick) left the run's saved state: put the player back before they play
        getServer().getScheduler().runTask(this, () -> { if (p.isOnline()) { restoreNow(p); p.sendMessage(Component.text("Your dungeon run ended while you were away. Everything is back.", NamedTextColor.YELLOW)); } });
    }

    // ------------------------------------------------------------------ saved state
    private File stateFile(UUID id) { return new File(stateDir, id + ".yml"); }

    private void saveState(Player p) {
        YamlConfiguration y = new YamlConfiguration();
        y.set("location", p.getLocation());
        y.set("gamemode", p.getGameMode().name());
        y.set("health", p.getHealth());
        y.set("food", p.getFoodLevel());
        y.set("saturation", (double) p.getSaturation());
        y.set("level", p.getLevel());
        y.set("exp", (double) p.getExp());
        y.set("inventory", Arrays.asList(p.getInventory().getContents()));
        y.set("effects", new ArrayList<>(p.getActivePotionEffects()));
        try { y.save(stateFile(p.getUniqueId())); } catch (IOException ex) { getLogger().warning("Could not save " + p.getName() + "'s state: " + ex.getMessage()); }
    }

    /** Puts everything back (no teleport wait): used on quit, disable, join-after-crash and finish. */
    private void restoreNow(Player p) {
        File f = stateFile(p.getUniqueId());
        if (!f.exists()) return;
        YamlConfiguration y = YamlConfiguration.loadConfiguration(f);
        try { p.setGameMode(GameMode.valueOf(y.getString("gamemode", "SURVIVAL"))); } catch (IllegalArgumentException ex) { p.setGameMode(GameMode.SURVIVAL); }
        List<?> inv = y.getList("inventory");
        if (inv != null) {
            ItemStack[] items = new ItemStack[p.getInventory().getContents().length];
            for (int i = 0; i < items.length && i < inv.size(); i++) items[i] = inv.get(i) instanceof ItemStack s ? s : null;
            p.getInventory().setContents(items);
        }
        for (PotionEffect e : p.getActivePotionEffects()) p.removePotionEffect(e.getType());
        List<?> fx = y.getList("effects");
        if (fx != null) for (Object o : fx) if (o instanceof PotionEffect pe) p.addPotionEffect(pe);
        p.setFoodLevel(y.getInt("food", 20));
        p.setSaturation((float) y.getDouble("saturation", 5.0));
        p.setLevel(y.getInt("level", 0));
        p.setExp((float) y.getDouble("exp", 0.0));
        try { p.setHealth(Math.max(1.0, y.getDouble("health", 20.0))); } catch (IllegalArgumentException ex) { p.setHealth(20.0); }
        Location back = y.getLocation("location");
        if (back == null || back.getWorld() == null) back = getServer().getWorlds().get(0).getSpawnLocation();
        p.teleport(back);
        f.delete();
    }

    /** End a run: restore the player (after the chunk of the old position is loaded), then unload and delete the run world. */
    private void finish(Player p, String message) {
        Run r = runs.remove(p.getUniqueId());
        if (r == null) return;
        if (r.bar != null) p.hideBossBar(r.bar);
        File f = stateFile(p.getUniqueId());
        Location back = f.exists() ? YamlConfiguration.loadConfiguration(f).getLocation("location") : null;
        Runnable done = () -> {
            restoreNow(p);
            p.sendMessage(Component.text(message, NamedTextColor.YELLOW));
            dispose(r);
        };
        if (back != null && back.getWorld() != null) {
            back.getWorld().getChunkAtAsync(back.getBlockX() >> 4, back.getBlockZ() >> 4).thenAccept(c -> getServer().getScheduler().runTask(this, done));
        } else done.run();
    }

    private void dispose(Run r) {
        World w = r.world != null ? r.world : getServer().getWorld(r.worldName);
        if (w == null) return;
        for (Player q : new ArrayList<>(w.getPlayers())) q.teleport(getServer().getWorlds().get(0).getSpawnLocation());
        File folder = w.getWorldFolder();
        if (getServer().unloadWorld(w, false) && isRunFolder(folder)) {
            if (isEnabled()) getServer().getScheduler().runTaskAsynchronously(this, () -> deleteTree(folder.toPath()));
            else deleteTree(folder.toPath());
        }
    }

    private static boolean isRunFolder(File f) { return f.getName().startsWith(PREFIX); }

    private static void deleteTree(Path root) {
        if (!root.getFileName().toString().startsWith(PREFIX)) return;      // never delete anything that is not a run world
        try (var walk = Files.walk(root)) {
            walk.sorted(java.util.Comparator.reverseOrder()).forEach(p -> p.toFile().delete());
        } catch (IOException ignored) { /* a locked file is retried by the next enable's sweep */ }
    }

    private void safeTeleport(Player p, Location to, Runnable after) {
        to.getWorld().getChunkAtAsync(to.getBlockX() >> 4, to.getBlockZ() >> 4).thenAccept(c -> getServer().getScheduler().runTask(this, () -> {
            if (!p.isOnline()) return;
            p.teleport(to);
            if (after != null) after.run();
        }));
    }
}
