#!/usr/bin/env tsx
// Golden corpus Test Flights + pass matrix (bundle mc-coverage). Run from a worktree on the primary (only ssh to node-2;
// the server itself boots on node-2 under the Test Flight runner, one flight at a time).
//
//   1. compile on node-2:   scripts/devhost run --lock -- node services/modbuilder/golden/harness.js
//   2. fly one version:     npx tsx scripts/cyrus/golden-flight.ts fly 1.21.11 [--out DIR] [--remote-out DIR]   (starter bank: --remote-out /tank/nxeon-build/tmp/testflight/starter-bank)
//      boots ONE Paper server with every golden jar that compiled for that version and runs each plugin's RCON checks
//      (golden.json "rcon"); writes <out>/flight-<version>.json (the raw report + a per-plugin verdict).
//   3. pass matrix:         npx tsx scripts/cyrus/golden-flight.ts results [--out DIR]
//      merges node-2's compile.json with the flight files into services/modbuilder/golden/results.json (committed)
//      and prints the per-archetype/per-version JSON for /root/agent-notes/cyrus-research/mc-coverage-flights-*.json.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, NODE2 } from "../../lib/cyrus/testflight/client";
import type { TestFlightReport, TestFlightSpec } from "../../lib/cyrus/testflight/types";


/** One flight at a time on node-2: when another agent's flight holds the runner lock, wait and retry (max ~20 min). */
async function flyWhenFree(spec: TestFlightSpec) {
  for (let i = 0; ; i++) {
    const r = await runTestFlight(spec);
    if (r.report.status !== "busy" || i >= 40) return r;
    await new Promise((res) => setTimeout(res, 30000));
  }
}

const ROOT = path.resolve(__dirname, "../..");
const argv = process.argv.slice(2);
const opt = (n: string, d: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : d; };
// --remote-out: another harness output on node-2 (the starter bank: /tank/nxeon-build/tmp/testflight/starter-bank)
const REMOTE_OUT = opt("remote-out", "/tank/nxeon-build/tmp/testflight/mc-coverage");
const OUT = opt("out", path.join(ROOT, ".cyrus-local", "golden"));
const ssh = (cmd: string) => execFileSync("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", NODE2, cmd], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });

type PluginVerdict = { plugin: string; enabled: boolean | null; rcon: { id: string; ok: boolean; text: string }[]; logHits: string[] };

/** Split one shared flight into per-plugin verdicts from the runner's evidence lines. */
export function perPlugin(report: TestFlightReport, names: Record<string, string>): Record<string, PluginVerdict> {
  const out: Record<string, PluginVerdict> = {};
  for (const [id, name] of Object.entries(names)) out[id] = { plugin: name, enabled: null, rcon: [], logHits: [] };
  const ev = (cid: string) => report.checks.find((c) => c.id === cid)?.evidence ?? [];
  for (const line of ev("plugins_enabled")) {
    const m = line.match(/^([A-Za-z0-9_.-]+): (enabled|NOT enabled)/);
    if (!m) continue;
    for (const v of Object.values(out)) if (v.plugin === m[1]) v.enabled = m[2] === "enabled";
  }
  for (const line of ev("rcon_checks")) {
    const m = line.match(/^([a-z0-9-]+)#(\d+) '.*?'.*?: (ok|FAILED)(.*)$/);
    if (m && out[m[1]]) out[m[1]].rcon.push({ id: `${m[1]}#${m[2]}`, ok: m[3] === "ok", text: m[4].replace(/^.*?-> /, "").slice(0, 200) });
  }
  for (const line of ev("startup_log_clean")) for (const v of Object.values(out)) if (line.includes(v.plugin)) v.logHits.push(line.slice(0, 240));
  return out;
}

async function fly(version: string) {
  const spec = JSON.parse(ssh(`cat ${REMOTE_OUT}/${version}/flight-spec.json`)) as { version: string; plugins: { remotePath: string; sha256: string }[]; rcon: TestFlightSpec["rcon"] };
  const compile = JSON.parse(ssh(`cat ${REMOTE_OUT}/compile.json`));
  const names: Record<string, string> = {};
  for (const [id, p] of Object.entries(compile.plugins as Record<string, { versions: Record<string, { pluginName?: string; jar?: string }> }>)) {
    const r = p.versions[version];
    if (r?.jar && spec.plugins.some((x) => x.remotePath === r.jar)) names[id] = r.pluginName!;
  }
  const tf: TestFlightSpec = {
    version, plugins: spec.plugins.map((p) => ({ remotePath: p.remotePath, sha256: p.sha256 })), rcon: spec.rcon,
    timeouts: { bootSec: 300, rconSec: 30, stopSec: 90, totalSec: 900 }, memory: { xmxMb: 1024, rssCapMb: 2048 },
  };
  console.log(`flying ${version}: ${tf.plugins!.length} plugins, ${tf.rcon!.length} RCON checks`);
  const t0 = Date.now();
  const { report, summary } = await flyWhenFree(tf);
  const verdicts = perPlugin(report, names);
  mkdirSync(OUT, { recursive: true });
  writeFileSync(path.join(OUT, `flight-${version}.json`), JSON.stringify({ version, wallMs: Date.now() - t0, summary, verdicts, report }, null, 1));
  console.log(`${version}: ${summary.overall} (boot ${summary.bootMs} ms, peak ${Math.round((summary.peakRssKb ?? 0) / 1024)} MB) failed=${summary.failed.join(",") || "-"}`);
  for (const [id, v] of Object.entries(verdicts)) {
    const bad = v.enabled === false || v.rcon.some((r) => !r.ok) || v.logHits.length;
    if (bad) console.log(`  ${id}: enabled=${v.enabled} ${v.rcon.filter((r) => !r.ok).map((r) => `${r.id} ${r.text}`).join(" | ")} ${v.logHits.join(" | ")}`);
  }
}

function results() {
  const compile = JSON.parse(ssh(`cat ${REMOTE_OUT}/compile.json`));
  const versions: string[] = compile.versions;
  const flights: { version: string; runId: string; overall: string; bootMs: number | null; plugins: number }[] = [];
  const fl: Record<string, { verdicts: Record<string, PluginVerdict> }> = {};
  for (const v of versions) {
    const f = path.join(OUT, `flight-${v}.json`);
    if (!existsSync(f)) continue;
    const j = JSON.parse(readFileSync(f, "utf8"));
    fl[v] = j;
    flights.push({ version: v, runId: j.summary.runId, overall: j.summary.overall, bootMs: j.summary.bootMs, plugins: Object.keys(j.verdicts).length });
  }
  const notesFile = path.join(ROOT, "services/modbuilder/golden/findings.json");
  const findings: Record<string, string[]> = existsSync(notesFile) ? JSON.parse(readFileSync(notesFile, "utf8")) : {};
  const rows = Object.entries(compile.plugins as Record<string, { archetype: string; versions: Record<string, { compile: string; scan: string; warnings?: string[]; findings?: unknown[] }> }>).map(([id, p]) => {
    const row = { id, archetype: p.archetype, compile: {} as Record<string, string>, scan: {} as Record<string, string>, boot: {} as Record<string, string>, ...(findings[id] ? { notes: findings[id] } : {}) };
    for (const v of versions) {
      const r = p.versions[v];
      row.compile[v] = r?.compile ?? "-";
      row.scan[v] = r?.scan ?? "-";
      const fv = fl[v]?.verdicts[id];
      row.boot[v] = r?.compile === "n/a" ? "n/a" : !fl[v] ? "-" : !fv ? "-" : fv.enabled && fv.rcon.every((x) => x.ok) && !fv.logHits.length ? "pass" : "fail";
    }
    return row;
  });
  const res = { schema: 1 as const, versions, flights, rows };
  writeFileSync(path.join(ROOT, "services/modbuilder/golden/results.json"), JSON.stringify(res, null, 1) + "\n");
  console.log(JSON.stringify({ generated: new Date().toISOString(), rulesVersion: compile.rulesVersion, ...res }, null, 1));
}

const cmd = argv[0];
if (cmd === "fly" && argv[1]) fly(argv[1]).catch((e) => { console.error(e); process.exit(2); });
else if (cmd === "results") results();
else { console.error("usage: golden-flight.ts fly <version> | results"); process.exit(2); }

