// Cyrus PROMPT COACH: "how does that work?" answers (pure, no model, zero cost). Owner incident 2026-10-15: the owner of
// the Infinite Dungeon mod did not know how a dungeon can be run in an existing world, and nobody told him. When a request
// implies a world that already exists ("my survival server") AND a dungeon / arena / minigame run, the coach answers the
// how in plain words (an instanced void world per run, the player's own state saved and restored, nothing of the existing
// world touched) and asks ONLY the questions that change the build and that the text has not answered yet.
// Facts are the verified ones in services/modbuilder/sheets (api-facts group "instanced") and the golden plugin
// services/modbuilder/golden/plugins/mc-instanced-dungeon-lite.
export const HOWTO_VERSION = 1;

export type HowAsk = { id: "runScope" | "partySize" | "persistence" | "startItems"; question: string; why: string; options: string[]; example: string };
export type HowTo = {
  id: "instanced-run";
  title: string;
  /** One sentence: the answer. */
  summary: string;
  steps: string[];
  /** What of the existing world is touched. */
  touches: string;
  limits: string[];
  /** Only the questions the text has not answered. */
  asks: HowAsk[];
};

const RUN_WORDS = /\b(dungeons?|roguelikes?|rogue-?lite|crawler|infinite dungeon|\d+ floors?|floor counter|arena|mini-?games?|spleef|bed ?wars|sky ?wars|boss (?:run|rush)|raid|instance[sd]?)\b/i;
const EXISTING_WORLD = /\b(?:in|on|for|inside) (?:my|our|the) (?:existing |current |main |own |normal |current )?(?:survival )?(?:world|server|smp|map)\b|\bexisting (?:survival )?(?:world|server|map)\b|\bmy (?:survival )?(?:world|server|smp)\b|\bwithout (?:touching|changing|breaking|editing|affecting) (?:my|the|our)\b|\b(?:must|should) (?:work|run) in (?:my|the|our)\b/i;
const INSTANCED = /\b(?:instanced?|separate|own|private|dedicated|temporary|void|empty) (?:world|dimension)\b|\bper[- ]run world\b/i;

/** The request implies a run inside a world that already exists (or says it wants an instance). */
export function wantsInstancedRun(text: string, context = ""): boolean {
  const t = `${context}\n${text}`;
  return RUN_WORDS.test(t) && (EXISTING_WORLD.test(t) || INSTANCED.test(t) || /\b(roguelike|rogue-?lite|infinite dungeon|dungeon crawler|\d{2,3} floors?)\b/i.test(t));
}

const ANSWERED: Record<HowAsk["id"], RegExp> = {
  runScope: /\b(solo|single[- ]player|per[- ]player|each player (?:gets|has|starts)|their own run|own run|private run|shared run|together|co-?op|party|team|everyone|groups?)\b/i,
  partySize: /\b(\d+ players?|up to \d+|party of \d+|max(?:imum)? (?:of )?\d+ players?|solo|single[- ]player|\d+ (?:people|friends))\b/i,
  persistence: /\b(save[sd]?|persist\w*|best floor|progress(?:ion)?|unlocks?|permanent|remember\w*|across (?:runs|restarts|sessions)|stats?)\b/i,
  startItems: /\b(bring(?:s)? (?:their|your|own)|empty inventory|start(?:s)? with (?:nothing|an? (?:empty|kit|basic|starter))|starter kit|starting (?:kit|gear|items)|keep(?:s)? (?:their|your) (?:own )?(?:items|gear|inventory)|own (?:items|gear))\b/i,
};

const ASKS: HowAsk[] = [
  { id: "runScope", question: "Is a run private to one player, or can others join the same run?",
    why: "One private world per player is simplest and safest; a shared run needs a party and a join rule.",
    options: ["Private: each player has their own run", "Shared: a player can invite others into their run"], example: "Each player has their own private run." },
  { id: "partySize", question: "How many players can be in one run?",
    why: "It sets how many mobs a room holds and how much work the server does per run.",
    options: ["1 player", "Up to 4 players", "Up to 8 players"], example: "Up to 4 players per run, 3 runs at the same time." },
  { id: "persistence", question: "What is remembered between runs and across server restarts?",
    why: "Saved progress needs a file per player; without it everything resets when a run or the server ends.",
    options: ["Best floor and stats per player, saved across restarts", "Nothing: every run starts fresh", "Permanent unlocks per player"], example: "Best floor and runs per player are saved across restarts." },
  { id: "startItems", question: "Do players bring their own items into a run?",
    why: "Their own items are always saved and returned untouched; this only decides what they hold inside the run.",
    options: ["Start with an empty inventory (their own items wait safely)", "Start with a small starter kit", "Bring their own gear in (they can lose it in the run)"], example: "Players start a run with an empty inventory; their own items are returned when it ends." },
];

/** The coach's answer for a request, or null when it does not imply a run in an existing world. */
export function howItWorks(text: string, context = ""): HowTo | null {
  if (!wantsInstancedRun(text, context)) return null;
  const t = `${context}\n${text}`;
  return {
    id: "instanced-run",
    title: "How a dungeon works in a world that already exists",
    summary: "Each run happens in its own separate, empty world that the plugin creates and removes. Your existing world is never entered, edited or reloaded; players are saved, moved, and put back exactly as they were.",
    steps: [
      "/dungeon start creates a private empty world for the run (nothing exists there except the rooms Cyrus places).",
      "Before anything changes, the plugin saves the player's own state to its data folder: location, inventory, game mode, health, food, level and potion effects.",
      "The player is moved into the run world. Floors, rooms and mobs exist only there.",
      "When the run ends (leave, abandon, finishing, or death) the saved state is put back and the player returns to the exact spot; the run world is unloaded and its folder deleted.",
      "If the player disconnects or the server stops mid-run, the state is restored on quit or on the next join, so nobody is left in the run world.",
    ],
    touches: "Nothing in your existing world is read, changed or deleted: no blocks, chunks, entities or settings. The only things added are the plugin's own saved states and the temporary run worlds, which are removed afterwards.",
    limits: [
      "Rooms are built from templates a few blocks at a time (not vanilla world generation), so a floor is placed over a second or two.",
      "Many runs at once cost server time: set how many runs may be active and how many mobs a room holds.",
      "A very large request (dozens of monsters, items and bosses) is built in stages, core first, so it finishes and each part can be tested.",
    ],
    asks: ASKS.filter((a) => !ANSWERED[a.id].test(t)),
  };
}
