// Cyrus MEGA STAGING (CM, 2026-10-15): the lessons of the Infinite Dungeon mod, offline. The fixture is the dungeon prompt
// (test/fixtures/cyrus-planner/dungeon-mega.json: one reconstructed full request + the six QA stage prompts).
//   1. mega-prompt detection + auto-staging (lib/cyrus/planner/mega.ts) and the chain (stop on a failed stage)
//   2. hold / estimate honesty (lib/cyrus/planner/honest.ts), measured from the owner batch records
//   3. planner code core (lib/cyrus/planner/policy.ts): no designer lane for an instanced / roguelike core, no regression
//   4. coach: how a dungeon works in an existing world (lib/cyrus/coach/howto.ts) + the dungeon_crawler archetype
//   5. knowledge: sheet line, failure rule, golden plugin, prompt growth under 3 percent
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { LARGE_THRESHOLD, MEGA_THRESHOLD, coverage, megaScore, nextStep, parseStageChain, planStages, splitClauses, stageBuildBody, STAGE_TEXT_MAX, megaStagingOn } from "../lib/cyrus/planner/mega";
import { HONEST_TABLE, CALL_CAP_USD, costClass, honestEstimate, honestOn } from "../lib/cyrus/planner/honest";
import { planEstimate } from "../lib/cyrus/planner/estimate";
import { ruleNeeds, mergeNeeds } from "../lib/cyrus/planner/rules";
import { applyCodeCore, codeCoreFor, codeCoreOn } from "../lib/cyrus/planner/policy";
import { decidePlan, builtLanes } from "../lib/cyrus/planner/decide";
import { buildModPlan, capabilityContext } from "../lib/cyrus/planner/run";
import { type Lane } from "../lib/cyrus/planner/lanes";
import { loadEvalSet, loadRealWorld } from "../lib/cyrus/eval/set";
import { parseTokenConfig } from "../lib/cyrus/tokens/config";
import { holdRange, tokensForCost } from "../lib/cyrus/tokens/economy";
import { analyzePrompt } from "../lib/cyrus/coach/analyze";
import { COACH_TEMPLATES, matchArchetype } from "../lib/cyrus/coach/archetypes";
import { howItWorks, wantsInstancedRun } from "../lib/cyrus/coach/howto";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const PR = require("../services/modbuilder/prompts.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PLN = require("../services/modbuilder/planner.js");

const ROOT = path.join(__dirname, "..");
const read = (p: string) => fs.readFileSync(path.join(ROOT, p), "utf8");
const FX = JSON.parse(read("test/fixtures/cyrus-planner/dungeon-mega.json")) as { full: string; stages: { stage: number; name: string; prompt: string }[] };
const FULL = FX.full;
const ALL_ON = { CYRUS_MEGA_STAGING: "1", CYRUS_HONEST_ESTIMATE: "1", CYRUS_CODE_CORE: "1" };
const built = (t: string): Lane[] => ruleNeeds(t).filter((n) => n.need && n.lane !== "config").map((n) => n.lane);
const withEnv = async <T>(env: Record<string, string>, f: () => Promise<T> | T): Promise<T> => {
  const old: Record<string, string | undefined> = {};
  for (const k of Object.keys(env)) { old[k] = process.env[k]; process.env[k] = env[k]; }
  try { return await f(); } finally { for (const [k, v] of Object.entries(old)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; } }
};
const corpus = (): string[] => [...loadRealWorld().map((p) => p.prompt), ...loadEvalSet().map((p) => p.prompt), ...(JSON.parse(read("test/fixtures/cyrus-planner/golden.json")).prompts as { text: string }[]).map((p) => p.text),
  ...(JSON.parse(read("test/fixtures/cyrus-planner/owner-batch-labels.json")).prompts as { text: string }[]).map((p) => p.text)];

describe("mega-prompt detection", () => {
  it("the dungeon request scores mega; every QA stage prompt and every corpus prompt stays below the staging threshold", () => {
    const s = megaScore(FULL, built(FULL).length);
    assert.equal(s.level, "mega");
    assert.ok(s.score >= MEGA_THRESHOLD, String(s.score));
    assert.ok(s.systems.length >= 10, `${s.systems.length} systems`);
    assert.ok(s.numbers.some((n) => n.noun === "floor" && n.n === 100) && s.numbers.some((n) => n.noun === "boss"));
    for (const st of FX.stages) assert.notEqual(megaScore(st.prompt, built(st.prompt).length).level, "mega", st.name);
    const top = Math.max(...corpus().map((t) => megaScore(t, built(t).length).score));
    assert.ok(top < LARGE_THRESHOLD, `the busiest corpus prompt scores ${top}`);
  });
  it("the score is deterministic and grows with systems, counts and length", () => {
    assert.equal(megaScore("a /heal command that heals the player, 10 second cooldown").level, "normal");
    assert.equal(megaScore(FULL).score, megaScore(FULL).score);
    assert.ok(megaScore(FULL + " " + FULL).score > megaScore(FULL).score);
  });
  it("flag CYRUS_MEGA_STAGING: off by default", () => { assert.equal(megaStagingOn({}), false); assert.equal(megaStagingOn({ CYRUS_MEGA_STAGING: "1" }), true); });
});

describe("auto-staging", () => {
  const plan = planStages(FULL, { laneCount: built(FULL).length, lanesOf: built });
  it("splits into an ordered core-first stage list and drops nothing", () => {
    assert.equal(plan.staged, true);
    assert.deepEqual(plan.stages.map((s) => s.kind), ["core", "content", "content", "content", "meta", "polish"]);
    assert.equal(plan.stages[0].kind, "core");
    assert.match(plan.stages[0].text, /\/dungeon start/);
    assert.match(plan.stages[0].text, /existing survival world/);
    const c = coverage(FULL, plan.stages);
    assert.deepEqual(c, { ok: true, missing: [], duplicated: [] });
    assert.deepEqual(plan.stages.flatMap((s) => s.clauses), splitClauses(FULL).slice().sort((a, b) => plan.stages.flatMap((s) => s.clauses).indexOf(a) - plan.stages.flatMap((s) => s.clauses).indexOf(b)));
  });
  it("content lands in its own stage: monsters, items, bosses, then meta and polish", () => {
    const by = (re: RegExp) => plan.stages.findIndex((s) => re.test(s.clauses.join(" ")));
    assert.ok(by(/custom monsters/) < by(/12 new items/));
    assert.ok(by(/12 new items/) < by(/10 distinct bosses/));
    assert.ok(by(/10 distinct bosses/) < by(/permanent upgrades/));
    assert.ok(by(/permanent upgrades/) < by(/run seed/));
    assert.ok(by(/100 floors/) === 0);
  });
  it("every refine stage fits a change request, keeps the earlier work, and is priced", () => {
    for (const [i, s] of plan.stages.entries()) {
      if (i > 0) { assert.ok(s.text.length <= STAGE_TEXT_MAX, `${s.id} ${s.text.length}`); assert.match(s.text, /Keep everything already built working/); }
      assert.ok(s.modules.length >= 1);
    }
  });
  it("a small request is not staged", () => {
    assert.equal(planStages("a /heal command with a 10 second cooldown and a config.yml message").staged, false);
  });
  it("with the flag on the plan response carries the stage list with per-stage tokens and the daily limit", async () => {
    const cfg = parseTokenConfig({});
    const { r, off } = await withEnv({ CYRUS_MEGA_STAGING: "1" }, async () => ({
      r: await buildModPlan({ text: FULL, game: "minecraft", mcVersion: "1.21.11", tier: "all", cfg, needs: ruleNeeds(FULL) }, { flags: {} }),
      off: await withEnv({ CYRUS_MEGA_STAGING: "0" }, () => buildModPlan({ text: FULL, game: "minecraft", mcVersion: "1.21.11", tier: "all", cfg, needs: ruleNeeds(FULL) }, { flags: {} })),
    }));
    assert.ok(r.mega?.staged);
    assert.equal(r.mega!.stages.length, 6);
    assert.ok(r.mega!.stages.every((s) => s.cost && s.cost.tokens && s.cost.tokens[1] >= s.cost.tokens[0] && s.cost.hold));
    assert.ok(r.mega!.total.tokens![1] > 0);
    assert.equal(r.mega!.dailyCap, cfg.dailyCap);
    assert.equal(off.mega, undefined, "flag off: no mega field");
  });
});

describe("the chain: change builds on the previous version, stops on a failed stage", () => {
  const plan = planStages(FULL, { laneCount: 7, lanesOf: built });
  const chain = { chainId: "c1abc234", index: 0, stages: plan.stages.map((s) => ({ id: s.id, title: s.title, text: s.text })), auto: true };
  it("parseStageChain validates, bounds and strips markup", () => {
    assert.ok(parseStageChain(chain));
    assert.equal(parseStageChain({ ...chain, index: 99 }), null);
    assert.equal(parseStageChain({ ...chain, chainId: "x" }), null);
    assert.equal(parseStageChain({ ...chain, stages: [chain.stages[0]] }), null);
    assert.equal(parseStageChain({ ...chain, stages: Array.from({ length: 12 }, () => chain.stages[0]) }), null);
    const p = parseStageChain({ ...chain, stages: chain.stages.map((s) => ({ ...s, text: `<b>${s.text}</b>`, title: `<i>${s.title}` })) })!;
    assert.ok(!/[<>]/.test(p.stages[0].text) && !/[<>]/.test(p.stages[0].title));
  });
  it("nextStep: wait while building, run the next on success, STOP on failure, done at the end", () => {
    assert.equal(nextStep(chain, "building").action, "wait");
    const run = nextStep(chain, "succeeded");
    assert.equal(run.action, "run");
    assert.equal(run.action === "run" && run.index, 1);
    const stop = nextStep({ ...chain, index: 2 }, "failed");
    assert.equal(stop.action, "stop");
    assert.match(stop.action === "stop" ? stop.reason : "", /Stage 3 .* did not finish/);
    assert.equal(nextStep({ ...chain, index: chain.stages.length - 1 }, "succeeded").action, "done");
  });
  it("the next stage is the ordinary refine body: baseBuildId + changeRequest, chain carried, nothing else invented", () => {
    const b = stageBuildBody(chain, "mbBASE")!;
    assert.equal(b.baseBuildId, "mbBASE");
    assert.equal(b.changeRequest, chain.stages[1].text);
    assert.equal((b.stageChain as { index: number }).index, 1);
    assert.equal(stageBuildBody({ ...chain, index: chain.stages.length - 1 }, "mbBASE"), null);
  });
  it("create.ts stores the chain only behind the flag and uses the same createModBuild path (no second pipeline)", () => {
    const s = read("lib/modbuilder/create.ts");
    assert.match(s, /megaStagingOn\(\) \? parseStageChain\(body\.stageChain\)/);
    assert.match(read("lib/cyrus/meta.ts"), /parseStageChain\(r\.stages\)/);
    assert.match(read("components/cyrus/app/StageChain.tsx"), /\/api\/mod-builder\/builds/);
    assert.doesNotMatch(read("components/cyrus/app/StageChain.tsx"), /\/api\/cyrus\/generate/);
  });
});

describe("hold / estimate honesty", () => {
  const M = JSON.parse(read("test/fixtures/cyrus-planner/measured-costs.json")) as { builds: { key: string; costUsd: number; wallSec: number; nonConfigLanes: number }[] };
  it("the table is re-derived from the owner batch records (n and the usd range per class)", () => {
    for (const [klass, lo, hi] of [["light", 0, 1], ["mid", 2, 3], ["heavy", 4, 99]] as const) {
      const rows = M.builds.filter((b) => b.nonConfigLanes >= lo && b.nonConfigLanes <= hi);
      const row = HONEST_TABLE[klass];
      assert.equal(row.n, rows.length, klass);
      const costs = rows.map((b) => b.costUsd);
      assert.ok(row.usd[1] >= Math.max(...costs) - 0.05, `${klass}: high ${row.usd[1]} covers the measured max ${Math.max(...costs)}`);
      assert.ok(row.usd[0] <= costs.sort((a, b) => a - b)[Math.floor(costs.length / 2)], `${klass}: low is at or under the measured median`);
      assert.ok(row.minutes[1] * 60 >= Math.max(...rows.map((b) => b.wallSec)) * 0.95, `${klass}: minutes cover the slowest build`);
    }
    assert.ok(HONEST_TABLE.mega.extrapolated && HONEST_TABLE.mega.usd[1] <= CALL_CAP_USD);
  });
  it("off by default: planEstimate is unchanged; on: never lower, mega class carries a warning", () => {
    assert.equal(honestOn({}), false);
    const lanes = built(FULL);
    const base = planEstimate(FULL, "saka", lanes, { honest: false });
    const honest = planEstimate(FULL, "saka", lanes, { honest: true });
    assert.equal(base.honest, undefined);
    assert.ok(honest.usd[0] >= base.usd[0] && honest.usd[1] > base.usd[1]);
    assert.ok(honest.minutes[1] >= base.minutes[1]);
    assert.equal(honest.honest?.klass, "mega");
    assert.match(honest.honest?.warning ?? "", /stages/);
    assert.ok(honest.honest?.extrapolated);
    const small = honestEstimate("shop gui with a /shop command, prices in config.yml", "saka", ["designMenu", "config"]);
    assert.equal(small.klass, costClass(1, "normal"));
    assert.equal(small.warning, null);
  });
  it("the hold follows: a mega request holds several times what the old estimate held", () => {
    const cfg = parseTokenConfig({});
    const lanes = built(FULL);
    const old = planEstimate(FULL, "saka", lanes, { honest: false });
    const now = planEstimate(FULL, "saka", lanes, { honest: true });
    const holdOld = holdRange("saka", old.complexity, cfg, old.usd)[1];
    const holdNow = holdRange("saka", now.complexity, cfg, now.usd)[1];
    assert.ok(holdNow > holdOld, `${holdNow} vs ${holdOld}`);
    assert.ok(holdNow >= tokensForCost(1.5, "saka", cfg));
  });
  it("a mid-size owner-batch build (fox companion, 0.98 usd) is no longer held at 350-600 tokens worth", () => {
    const fox = "a friendly fox companion that follows you around and fetches dropped items for you, with its own texture. tameable with sweet berries";
    const lanes: Lane[] = ["texture", "creature", "designItem", "config"];
    const cfg = parseTokenConfig({});
    const old = planEstimate(fox, "saka", lanes, { honest: false });
    const now = planEstimate(fox, "saka", lanes, { honest: true });
    assert.ok(now.usd[1] >= 1.1 && now.usd[1] > old.usd[1], `${now.usd} vs ${old.usd}`);
    assert.ok(holdRange("saka", now.complexity, cfg, now.usd)[1] > holdRange("saka", old.complexity, cfg, old.usd)[1]);
  });
});

describe("planner code core", () => {
  it("the dungeon request: archetypes recognised; flag off = lanes unchanged; flag on = no designer lane and no worldgen", () => {
    const ids = codeCoreFor(FULL).map((c) => c.id);
    assert.ok(ids.includes("instanced-world") && ids.includes("roguelike"));
    const off = built(FULL);
    assert.ok(off.some((l) => l.startsWith("design") || l === "motion"), `designer lanes on without the flag: ${off.join(",")}`);
    const on = applyCodeCore(ruleNeeds(FULL), FULL, { on: true }).filter((n) => n.need).map((n) => n.lane);
    for (const l of ["designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "worldgen"] as Lane[]) assert.ok(!on.includes(l), l);
    assert.equal(codeCoreOn({}), false);
  });
  it("the stage-1 core text alone (no designer words) is still a code-core mod", () => {
    const core = FX.stages[0].prompt;
    const on = applyCodeCore(ruleNeeds(core), core, { on: true }).filter((n) => n.need).map((n) => n.lane);
    assert.deepEqual(on.filter((l) => l.startsWith("design") || l === "motion" || l === "worldgen"), []);
  });
  it("a later change request inherits the code core of its mod (context)", async () => {
    const change = FX.stages[3].prompt; // "Add bosses ..."
    assert.deepEqual(codeCoreFor(change).map((c) => c.id), []);
    const { ctx, catalogue } = capabilityContext("minecraft", "1.21.11", { CYRUS_DESIGNER: true });
    const mk = (context?: string) => builtLanes(decidePlan({ needs: ruleNeeds(change), source: "rules", catalogue, ctx, plan: "all", change: true, text: change, context, codeCore: true }));
    assert.ok(mk().includes("designBoss"));
    assert.ok(!mk(FX.stages[0].prompt).includes("designBoss"));
  });
  it("plan card: one honest line says the core is plugin code; an explicit toggle still wins", () => {
    const { ctx, catalogue } = capabilityContext("minecraft", "1.21.11", { CYRUS_DESIGNER: true });
    const p = decidePlan({ needs: applyCodeCore(ruleNeeds(FULL), FULL, { on: true }), source: "rules", catalogue, ctx, plan: "all", text: FULL, codeCore: true });
    assert.equal(p.notes[0].kind, "core");
    assert.match(p.notes[0].text, /plugin code/);
    assert.ok(p.notes.some((n) => n.kind === "code" && n.lane === "designHud"));
    const t = decidePlan({ needs: applyCodeCore(ruleNeeds(FULL), FULL, { on: true }), source: "rules", catalogue, ctx, plan: "all", text: FULL, codeCore: true, toggles: { designHud: true } });
    assert.equal(t.lanes.find((l) => l.lane === "designHud")!.state, "build");
  });
  it("no regression: with the flag ON every lane of every corpus prompt (real-world 80, evalset, golden, owner batch) is identical", () => {
    const texts = corpus();
    assert.ok(texts.length > 400);
    let hit = 0;
    for (const t of texts) {
      const a = ruleNeeds(t).filter((n) => n.need).map((n) => n.lane).join(",");
      const b = applyCodeCore(ruleNeeds(t), t, { on: true }).filter((n) => n.need).map((n) => n.lane).join(",");
      if (a !== b) { hit++; assert.fail(`lanes changed for: ${t.slice(0, 120)} (${a} -> ${b})`); }
    }
    assert.equal(hit, 0);
  });
  it("the model path: a model that plans designMenu/designHud/worldgen for the dungeon is corrected by the same policy", () => {
    const planner = ruleNeeds(FULL).map((n) => (["designMenu", "designHud", "config", "worldgen"].includes(n.lane) ? { ...n, need: true, why: "model", confidence: 0.9 } : { ...n, need: false }));
    const m = mergeNeeds(planner, FULL);
    const flagged = applyCodeCore(m.lanes, FULL, { on: true }).filter((n) => n.need).map((n) => n.lane);
    assert.deepEqual(flagged.filter((l) => l !== "config" && !/^(texture|sound|creature|datapack|library|itemStates|model3d)$/.test(l)), []);
  });
  it("the planner model prompt says a code-core mod is plain code (needs the image bump to take effect)", () => {
    assert.match(PLN.PLANNER_PROMPT, /heart is code/);
  });
});

describe("coach: how a dungeon works in an existing world", () => {
  const ask = "I want a dungeon for my survival server, it must work in my existing world without touching it. /dungeon start sends a player into rooms with monsters, 10 floors.";
  it("a dungeon in an existing world gets the answer and only the questions the text has not answered", () => {
    assert.equal(wantsInstancedRun(ask), true);
    const h = howItWorks(ask)!;
    assert.match(h.summary, /own separate, empty world/);
    assert.ok(h.steps.some((s) => /saves the player's own state/.test(s)));
    assert.match(h.touches, /Nothing in your existing world/);
    const ids = h.asks.map((a) => a.id);
    assert.ok(ids.includes("runScope") && ids.includes("partySize") && ids.includes("startItems"));
    const answered = howItWorks(`${ask} Each player has their own run, solo, up to 1 players, they start with an empty inventory and their best floor is saved.`)!;
    assert.deepEqual(answered.asks.map((a) => a.id), []);
  });
  it("the report carries it and the archetype is dungeon_crawler; plain requests get none", () => {
    const r = analyzePrompt({ text: ask, version: "1.21.11" });
    assert.equal(r.archetype?.id, "dungeon_crawler");
    assert.ok(r.howItWorks);
    assert.equal(analyzePrompt({ text: "a /heal command with a 10 second cooldown", version: "1.21.11" }).howItWorks, undefined);
    assert.equal(analyzePrompt({ text: "spleef minigame. /spleef join, arena with snow floor, last player standing wins, countdown, lobby, scoreboard", version: "1.21.11" }).howItWorks, undefined);
    assert.equal(matchArchetype("spleef minigame. /spleef join, arena with snow floor, last player standing wins")?.id, "minigames_arenas");
    assert.equal(matchArchetype(FULL)?.id, "dungeon_crawler");
    assert.ok(COACH_TEMPLATES.some((t) => t.id === "dungeon_crawler"));
  });
  it("the arena in an existing world also gets the how (the same instanced-world answer)", () => {
    assert.equal(wantsInstancedRun("an arena minigame for my existing survival server that must not touch the world"), true);
  });
});

describe("knowledge for the code core", () => {
  const versions = ["1.21.1", "1.21.4", "1.21.8", "1.21.11"];
  it("every sheet has the instanced-worlds line with javap-verified facts", () => {
    const verified = JSON.parse(read("services/modbuilder/sheets/api-facts.verified.json")) as { facts: Record<string, Record<string, { present: boolean; members: Record<string, { present: boolean }> }>> };
    const ids = Object.keys(verified.facts).filter((k) => k.startsWith("Instanced."));
    assert.ok(ids.length >= 7);
    for (const v of versions) {
      const sheet = read(`services/modbuilder/sheets/${v}.md`);
      assert.match(sheet, /Instanced run worlds \(a private void world per run/);
      for (const id of ids) assert.ok(verified.facts[id][v].present && Object.values(verified.facts[id][v].members).every((m) => m.present), `${id} ${v}`);
    }
  });
  it("prompt growth from this round stays under 3 percent on every version", () => {
    const BASE: Record<string, number> = { "1.21.1": 55554, "1.21.4": 56565, "1.21.8": 56795, "1.21.11": 58670 }; // chars before the instanced facts + rule
    for (const v of versions) {
      const n = PR.systemPrompt(v).length;
      assert.ok(n > BASE[v] - 2500, v);
      assert.ok(n <= BASE[v] * 1.03, `${v}: ${n} vs ${BASE[v]} = +${(((n - BASE[v]) / BASE[v]) * 100).toFixed(2)}%`);
    }
  });
  it("the failure rule is injected and the golden plugin is registered in the corpus", () => {
    assert.ok(PR.systemPrompt("1.21.11").includes("A world made for one run must be unloaded"));
    const gp = "services/modbuilder/golden/plugins/mc-instanced-dungeon-lite";
    const java = read(`${gp}/src/dev/nxeon/golden/dungeon/Dungeon.java`);
    for (const must of ["new WorldCreator(", "extends ChunkGenerator", "unloadWorld(", "getContents()", "setKeepInventory(true)", "BossBar.bossBar(", "deleteTree"]) assert.ok(java.includes(must), must);
    assert.equal(JSON.parse(read(`${gp}/golden.json`)).archetype, "dungeon_crawler");
    const res = JSON.parse(read("services/modbuilder/golden/results.json")) as { rows: { id: string; compile: Record<string, string>; scan: Record<string, string>; boot: Record<string, string> }[] };
    const row = res.rows.find((r) => r.id === "mc-instanced-dungeon-lite")!;
    for (const v of versions) { assert.equal(row.compile[v], "pass"); assert.equal(row.scan[v], "pass"); }
    assert.equal(row.boot["1.21.11"], "pass");
    const cov = JSON.parse(read("lib/cyrus/adapters/minecraft-coverage.json")) as { archetypes: { id: string; golden?: string }[] };
    assert.equal(cov.archetypes.find((a) => a.id === "dungeon_crawler")?.golden, "mc-instanced-dungeon-lite");
  });
});

toolu_01FwLnuqPzJtXXfyjtereL7L.content:
// Cyrus MEGA STAGING (CM, 2026-10-15): the lessons of the Infinite Dungeon mod, offline. The fixture is the dungeon prompt
// (test/fixtures/cyrus-planner/dungeon-mega.json: one reconstructed full request + the six QA stage prompts).
//   1. mega-prompt detection + auto-staging (lib/cyrus/planner/mega.ts) and the chain (stop on a failed stage)
//   2. hold / estimate honesty (lib/cyrus/planner/honest.ts), measured from the owner batch records
//   3. planner code core (lib/cyrus/planner/policy.ts): no designer lane for an instanced / roguelike core, no regression
//   4. coach: how a dungeon works in an existing world (lib/cyrus/coach/howto.ts) + the dungeon_crawler archetype
//   5. knowledge: sheet line, failure rule, golden plugin, prompt growth under 3 percent
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { LARGE_THRESHOLD, MEGA_THRESHOLD, coverage, megaScore, nextStep, parseStageChain, planStages, splitClauses, stageBuildBody, STAGE_TEXT_MAX, megaStagingOn } from "../lib/cyrus/planner/mega";
import { HONEST_TABLE, CALL_CAP_USD, costClass, honestEstimate, honestOn } from "../lib/cyrus/planner/honest";
import { planEstimate } from "../lib/cyrus/planner/estimate";
import { ruleNeeds, mergeNeeds } from "../lib/cyrus/planner/rules";
import { applyCodeCore, codeCoreFor, codeCoreOn } from "../lib/cyrus/planner/policy";
import { decidePlan, builtLanes } from "../lib/cyrus/planner/decide";
import { buildModPlan, capabilityContext } from "../lib/cyrus/planner/run";
import { type Lane } from "../lib/cyrus/planner/lanes";
import { loadEvalSet, loadRealWorld } from "../lib/cyrus/eval/set";
import { parseTokenConfig } from "../lib/cyrus/tokens/config";
import { holdRange, tokensForCost } from "../lib/cyrus/tokens/economy";
import { analyzePrompt } from "../lib/cyrus/coach/analyze";
import { COACH_TEMPLATES, matchArchetype } from "../lib/cyrus/coach/archetypes";
import { howItWorks, wantsInstancedRun } from "../lib/cyrus/coach/howto";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const PR = require("../services/modbuilder/prompts.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PLN = require("../services/modbuilder/planner.js");

const ROOT = path.join(__dirname, "..");
const read = (p: string) => fs.readFileSync(path.join(ROOT, p), "utf8");
const FX = JSON.parse(read("test/fixtures/cyrus-planner/dungeon-mega.json")) as { full: string; stages: { stage: number; name: string; prompt: string }[] };
const FULL = FX.full;
const ALL_ON = { CYRUS_MEGA_STAGING: "1", CYRUS_HONEST_ESTIMATE: "1", CYRUS_CODE_CORE: "1" };
const built = (t: string): Lane[] => ruleNeeds(t).filter((n) => n.need && n.lane !== "config").map((n) => n.lane);
const withEnv = async <T>(env: Record<string, string>, f: () => Promise<T> | T): Promise<T> => {
  const old: Record<string, string | undefined> = {};
  for (const k of Object.keys(env)) { old[k] = process.env[k]; process.env[k] = env[k]; }
  try { return await f(); } finally { for (const [k, v] of Object.entries(old)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; } }
};
const corpus = (): string[] => [...loadRealWorld().map((p) => p.prompt), ...loadEvalSet().map((p) => p.prompt), ...(JSON.parse(read("test/fixtures/cyrus-planner/golden.json")).prompts as { text: string }[]).map((p) => p.text),
  ...(JSON.parse(read("test/fixtures/cyrus-planner/owner-batch-labels.json")).prompts as { text: string }[]).map((p) => p.text)];

describe("mega-prompt detection", () => {
  it("the dungeon request scores mega; every QA stage prompt and every corpus prompt stays below the staging threshold", () => {
    const s = megaScore(FULL, built(FULL).length);
    assert.equal(s.level, "mega");
    assert.ok(s.score >= MEGA_THRESHOLD, String(s.score));
    assert.ok(s.systems.length >= 10, `${s.systems.length} systems`);
    assert.ok(s.numbers.some((n) => n.noun === "floor" && n.n === 100) && s.numbers.some((n) => n.noun === "boss"));
    for (const st of FX.stages) assert.notEqual(megaScore(st.prompt, built(st.prompt).length).level, "mega", st.name);
    const top = Math.max(...corpus().map((t) => megaScore(t, built(t).length).score));
    assert.ok(top < LARGE_THRESHOLD, `the busiest corpus prompt scores ${top}`);
  });
  it("the score is deterministic and grows with systems, counts and length", () => {
    assert.equal(megaScore("a /heal command that heals the player, 10 second cooldown").level, "normal");
    assert.equal(megaScore(FULL).score, megaScore(FULL).score);
    assert.ok(megaScore(FULL + " " + FULL).score > megaScore(FULL).score);
  });
  it("flag CYRUS_MEGA_STAGING: off by default", () => { assert.equal(megaStagingOn({}), false); assert.equal(megaStagingOn({ CYRUS_MEGA_STAGING: "1" }), true); });
});

describe("auto-staging", () => {
  const plan = planStages(FULL, { laneCount: built(FULL).length, lanesOf: built });
  it("splits into an ordered core-first stage list and drops nothing", () => {
    assert.equal(plan.staged, true);
    assert.deepEqual(plan.stages.map((s) => s.kind), ["core", "content", "content", "content", "meta", "polish"]);
    assert.equal(plan.stages[0].kind, "core");
    assert.match(plan.stages[0].text, /\/dungeon start/);
    assert.match(plan.stages[0].text, /existing survival world/);
    const c = coverage(FULL, plan.stages);
    assert.deepEqual(c, { ok: true, missing: [], duplicated: [] });
    assert.deepEqual(plan.stages.flatMap((s) => s.clauses), splitClauses(FULL).slice().sort((a, b) => plan.stages.flatMap((s) => s.clauses).indexOf(a) - plan.stages.flatMap((s) => s.clauses).indexOf(b)));
  });
  it("content lands in its own stage: monsters, items, bosses, then meta and polish", () => {
    const by = (re: RegExp) => plan.stages.findIndex((s) => re.test(s.clauses.join(" ")));
    assert.ok(by(/custom monsters/) < by(/12 new items/));
    assert.ok(by(/12 new items/) < by(/10 distinct bosses/));
    assert.ok(by(/10 distinct bosses/) < by(/permanent upgrades/));
    assert.ok(by(/permanent upgrades/) < by(/run seed/));
    assert.ok(by(/100 floors/) === 0);
  });
  it("every refine stage fits a change request, keeps the earlier work, and is priced", () => {
    for (const [i, s] of plan.stages.entries()) {
      if (i > 0) { assert.ok(s.text.length <= STAGE_TEXT_MAX, `${s.id} ${s.text.length}`); assert.match(s.text, /Keep everything already built working/); }
      assert.ok(s.modules.length >= 1);
    }
  });
  it("a small request is not staged", () => {
    assert.equal(planStages("a /heal command with a 10 second cooldown and a config.yml message").staged, false);
  });
  it("with the flag on the plan response carries the stage list with per-stage tokens and the daily limit", async () => {
    const cfg = parseTokenConfig({});
    const { r, off } = await withEnv({ CYRUS_MEGA_STAGING: "1" }, async () => ({
      r: await buildModPlan({ text: FULL, game: "minecraft", mcVersion: "1.21.11", tier: "all", cfg, needs: ruleNeeds(FULL) }, { flags: {} }),
      off: await withEnv({ CYRUS_MEGA_STAGING: "0" }, () => buildModPlan({ text: FULL, game: "minecraft", mcVersion: "1.21.11", tier: "all", cfg, needs: ruleNeeds(FULL) }, { flags: {} })),
    }));
    assert.ok(r.mega?.staged);
    assert.equal(r.mega!.stages.length, 6);
    assert.ok(r.mega!.stages.every((s) => s.cost && s.cost.tokens && s.cost.tokens[1] >= s.cost.tokens[0] && s.cost.hold));
    assert.ok(r.mega!.total.tokens![1] > 0);
    assert.equal(r.mega!.dailyCap, cfg.dailyCap);
    assert.equal(off.mega, undefined, "flag off: no mega field");
  });
});

describe("the chain: change builds on the previous version, stops on a failed stage", () => {
  const plan = planStages(FULL, { laneCount: 7, lanesOf: built });
  const chain = { chainId: "c1abc234", index: 0, stages: plan.stages.map((s) => ({ id: s.id, title: s.title, text: s.text })), auto: true };
  it("parseStageChain validates, bounds and strips markup", () => {
    assert.ok(parseStageChain(chain));
    assert.equal(parseStageChain({ ...chain, index: 99 }), null);
    assert.equal(parseStageChain({ ...chain, chainId: "x" }), null);
    assert.equal(parseStageChain({ ...chain, stages: [chain.stages[0]] }), null);
    assert.equal(parseStageChain({ ...chain, stages: Array.from({ length: 12 }, () => chain.stages[0]) }), null);
    const p = parseStageChain({ ...chain, stages: chain.stages.map((s) => ({ ...s, text: `<b>${s.text}</b>`, title: `<i>${s.title}` })) })!;
    assert.ok(!/[<>]/.test(p.stages[0].text) && !/[<>]/.test(p.stages[0].title));
  });
  it("nextStep: wait while building, run the next on success, STOP on failure, done at the end", () => {
    assert.equal(nextStep(chain, "building").action, "wait");
    const run = nextStep(chain, "succeeded");
    assert.equal(run.action, "run");
    assert.equal(run.action === "run" && run.index, 1);
    const stop = nextStep({ ...chain, index: 2 }, "failed");
    assert.equal(stop.action, "stop");
    assert.match(stop.action === "stop" ? stop.reason : "", /Stage 3 .* did not finish/);
    assert.equal(nextStep({ ...chain, index: chain.stages.length - 1 }, "succeeded").action, "done");
  });
  it("the next stage is the ordinary refine body: baseBuildId + changeRequest, chain carried, nothing else invented", () => {
    const b = stageBuildBody(chain, "mbBASE")!;
    assert.equal(b.baseBuildId, "mbBASE");
    assert.equal(b.changeRequest, chain.stages[1].text);
    assert.equal((b.stageChain as { index: number }).index, 1);
    assert.equal(stageBuildBody({ ...chain, index: chain.stages.length - 1 }, "mbBASE"), null);
  });
  it("create.ts stores the chain only behind the flag and uses the same createModBuild path (no second pipeline)", () => {
    const s = read("lib/modbuilder/create.ts");
    assert.match(s, /megaStagingOn\(\) \? parseStageChain\(body\.stageChain\)/);
    assert.match(read("lib/cyrus/meta.ts"), /parseStageChain\(r\.stages\)/);
    assert.match(read("components/cyrus/app/StageChain.tsx"), /\/api\/mod-builder\/builds/);
    assert.doesNotMatch(read("components/cyrus/app/StageChain.tsx"), /\/api\/cyrus\/generate/);
  });
});

describe("hold / estimate honesty", () => {
  const M = JSON.parse(read("test/fixtures/cyrus-planner/measured-costs.json")) as { builds: { key: string; costUsd: number; wallSec: number; nonConfigLanes: number }[] };
  it("the table is re-derived from the owner batch records (n and the usd range per class)", () => {
    for (const [klass, lo, hi] of [["light", 0, 1], ["mid", 2, 3], ["heavy", 4, 99]] as const) {
      const rows = M.builds.filter((b) => b.nonConfigLanes >= lo && b.nonConfigLanes <= hi);
      const row = HONEST_TABLE[klass];
      assert.equal(row.n, rows.length, klass);
      const costs = rows.map((b) => b.costUsd);
      assert.ok(row.usd[1] >= Math.max(...costs) - 0.05, `${klass}: high ${row.usd[1]} covers the measured max ${Math.max(...costs)}`);
      assert.ok(row.usd[0] <= costs.sort((a, b) => a - b)[Math.floor(costs.length / 2)], `${klass}: low is at or under the measured median`);
      assert.ok(row.minutes[1] * 60 >= Math.max(...rows.map((b) => b.wallSec)) * 0.95, `${klass}: minutes cover the slowest build`);
    }
    assert.ok(HONEST_TABLE.mega.extrapolated && HONEST_TABLE.mega.usd[1] <= CALL_CAP_USD);
  });
  it("off by default: planEstimate is unchanged; on: never lower, mega class carries a warning", () => {
    assert.equal(honestOn({}), false);
    const lanes = built(FULL);
    const base = planEstimate(FULL, "saka", lanes, { honest: false });
    const honest = planEstimate(FULL, "saka", lanes, { honest: true });
    assert.equal(base.honest, undefined);
    assert.ok(honest.usd[0] >= base.usd[0] && honest.usd[1] > base.usd[1]);
    assert.ok(honest.minutes[1] >= base.minutes[1]);
    assert.equal(honest.honest?.klass, "mega");
    assert.match(honest.honest?.warning ?? "", /stages/);
    assert.ok(honest.honest?.extrapolated);
    const small = honestEstimate("shop gui with a /shop command, prices in config.yml", "saka", ["designMenu", "config"]);
    assert.equal(small.klass, costClass(1, "normal"));
    assert.equal(small.warning, null);
  });
  it("the hold follows: a mega request holds several times what the old estimate held", () => {
    const cfg = parseTokenConfig({});
    const lanes = built(FULL);
    const old = planEstimate(FULL, "saka", lanes, { honest: false });
    const now = planEstimate(FULL, "saka", lanes, { honest: true });
    const holdOld = holdRange("saka", old.complexity, cfg, old.usd)[1];
    const holdNow = holdRange("saka", now.complexity, cfg, now.usd)[1];
    assert.ok(holdNow > holdOld, `${holdNow} vs ${holdOld}`);
    assert.ok(holdNow >= tokensForCost(1.5, "saka", cfg));
  });
  it("a mid-size owner-batch build (fox companion, 0.98 usd) is no longer held at 350-600 tokens worth", () => {
    const fox = "a friendly fox companion that follows you around and fetches dropped items for you, with its own texture. tameable with sweet berries";
    const lanes: Lane[] = ["texture", "creature", "designItem", "config"];
    const cfg = parseTokenConfig({});
    const old = planEstimate(fox, "saka", lanes, { honest: false });
    const now = planEstimate(fox, "saka", lanes, { honest: true });
    assert.ok(now.usd[1] >= 1.1 && now.usd[1] > old.usd[1], `${now.usd} vs ${old.usd}`);
    assert.ok(holdRange("saka", now.complexity, cfg, now.usd)[1] > holdRange("saka", old.complexity, cfg, old.usd)[1]);
  });
});

describe("planner code core", () => {
  it("the dungeon request: archetypes recognised; flag off = lanes unchanged; flag on = no designer lane and no worldgen", () => {
    const ids = codeCoreFor(FULL).map((c) => c.id);
    assert.ok(ids.includes("instanced-world") && ids.includes("roguelike"));
    const off = built(FULL);
    assert.ok(off.some((l) => l.startsWith("design") || l === "motion"), `designer lanes on without the flag: ${off.join(",")}`);
    const on = applyCodeCore(ruleNeeds(FULL), FULL, { on: true }).filter((n) => n.need).map((n) => n.lane);
    for (const l of ["designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "worldgen"] as Lane[]) assert.ok(!on.includes(l), l);
    assert.equal(codeCoreOn({}), false);
  });
  it("the stage-1 core text alone (no designer words) is still a code-core mod", () => {
    const core = FX.stages[0].prompt;
    const on = applyCodeCore(ruleNeeds(core), core, { on: true }).filter((n) => n.need).map((n) => n.lane);
    assert.deepEqual(on.filter((l) => l.startsWith("design") || l === "motion" || l === "worldgen"), []);
  });
  it("a later change request inherits the code core of its mod (context)", async () => {
    const change = FX.stages[3].prompt; // "Add bosses ..."
    assert.deepEqual(codeCoreFor(change).map((c) => c.id), []);
    const { ctx, catalogue } = capabilityContext("minecraft", "1.21.11", { CYRUS_DESIGNER: true });
    const mk = (context?: string) => builtLanes(decidePlan({ needs: ruleNeeds(change), source: "rules", catalogue, ctx, plan: "all", change: true, text: change, context, codeCore: true }));
    assert.ok(mk().includes("designBoss"));
    assert.ok(!mk(FX.stages[0].prompt).includes("designBoss"));
  });
  it("plan card: one honest line says the core is plugin code; an explicit toggle still wins", () => {
    const { ctx, catalogue } = capabilityContext("minecraft", "1.21.11", { CYRUS_DESIGNER: true });
    const p = decidePlan({ needs: applyCodeCore(ruleNeeds(FULL), FULL, { on: true }), source: "rules", catalogue, ctx, plan: "all", text: FULL, codeCore: true });
    assert.equal(p.notes[0].kind, "core");
    assert.match(p.notes[0].text, /plugin code/);
    assert.ok(p.notes.some((n) => n.kind === "code" && n.lane === "designHud"));
    const t = decidePlan({ needs: applyCodeCore(ruleNeeds(FULL), FULL, { on: true }), source: "rules", catalogue, ctx, plan: "all", text: FULL, codeCore: true, toggles: { designHud: true } });
    assert.equal(t.lanes.find((l) => l.lane === "designHud")!.state, "build");
  });
  it("no regression: with the flag ON every lane of every corpus prompt (real-world 80, evalset, golden, owner batch) is identical", () => {
    const texts = corpus();
    assert.ok(texts.length > 400);
    let hit = 0;
    for (const t of texts) {
      const a = ruleNeeds(t).filter((n) => n.need).map((n) => n.lane).join(",");
      const b = applyCodeCore(ruleNeeds(t), t, { on: true }).filter((n) => n.need).map((n) => n.lane).join(",");
      if (a !== b) { hit++; assert.fail(`lanes changed for: ${t.slice(0, 120)} (${a} -> ${b})`); }
    }
    assert.equal(hit, 0);
  });
  it("the model path: a model that plans designMenu/designHud/worldgen for the dungeon is corrected by the same policy", () => {
    const planner = ruleNeeds(FULL).map((n) => (["designMenu", "designHud", "config", "worldgen"].includes(n.lane) ? { ...n, need: true, why: "model", confidence: 0.9 } : { ...n, need: false }));
    const m = mergeNeeds(planner, FULL);
    const flagged = applyCodeCore(m.lanes, FULL, { on: true }).filter((n) => n.need).map((n) => n.lane);
    assert.deepEqual(flagged.filter((l) => l !== "config" && !/^(texture|sound|creature|datapack|library|itemStates|model3d)$/.test(l)), []);
  });
  it("the planner model prompt says a code-core mod is plain code (needs the image bump to take effect)", () => {
    assert.match(PLN.PLANNER_PROMPT, /heart is code/);
  });
});

describe("coach: how a dungeon works in an existing world", () => {
  const ask = "I want a dungeon for my survival server, it must work in my existing world without touching it. /dungeon start sends a player into rooms with monsters, 10 floors.";
  it("a dungeon in an existing world gets the answer and only the questions the text has not answered", () => {
    assert.equal(wantsInstancedRun(ask), true);
    const h = howItWorks(ask)!;
    assert.match(h.summary, /own separate, empty world/);
    assert.ok(h.steps.some((s) => /saves the player's own state/.test(s)));
    assert.match(h.touches, /Nothing in your existing world/);
    const ids = h.asks.map((a) => a.id);
    assert.ok(ids.includes("runScope") && ids.includes("partySize") && ids.includes("startItems"));
    const answered = howItWorks(`${ask} Each player has their own run, solo, up to 1 players, they start with an empty inventory and their best floor is saved.`)!;
    assert.deepEqual(answered.asks.map((a) => a.id), []);
  });
  it("the report carries it and the archetype is dungeon_crawler; plain requests get none", () => {
    const r = analyzePrompt({ text: ask, version: "1.21.11" });
    assert.equal(r.archetype?.id, "dungeon_crawler");
    assert.ok(r.howItWorks);
    assert.equal(analyzePrompt({ text: "a /heal command with a 10 second cooldown", version: "1.21.11" }).howItWorks, undefined);
    assert.equal(analyzePrompt({ text: "spleef minigame. /spleef join, arena with snow floor, last player standing wins, countdown, lobby, scoreboard", version: "1.21.11" }).howItWorks, undefined);
    assert.equal(matchArchetype("spleef minigame. /spleef join, arena with snow floor, last player standing wins")?.id, "minigames_arenas");
    assert.equal(matchArchetype(FULL)?.id, "dungeon_crawler");
    assert.ok(COACH_TEMPLATES.some((t) => t.id === "dungeon_crawler"));
  });
  it("the arena in an existing world also gets the how (the same instanced-world answer)", () => {
    assert.equal(wantsInstancedRun("an arena minigame for my existing survival server that must not touch the world"), true);
  });
});

describe("knowledge for the code core", () => {
  const versions = ["1.21.1", "1.21.4", "1.21.8", "1.21.11"];
  it("every sheet has the instanced-worlds line with javap-verified facts", () => {
    const verified = JSON.parse(read("services/modbuilder/sheets/api-facts.verified.json")) as { facts: Record<string, Record<string, { present: boolean; members: Record<string, { present: boolean }> }>> };
    const ids = Object.keys(verified.facts).filter((k) => k.startsWith("Instanced."));
    assert.ok(ids.length >= 7);
    for (const v of versions) {
      const sheet = read(`services/modbuilder/sheets/${v}.md`);
      assert.match(sheet, /Instanced run worlds \(a private void world per run/);
      for (const id of ids) assert.ok(verified.facts[id][v].present && Object.values(verified.facts[id][v].members).every((m) => m.present), `${id} ${v}`);
    }
  });
  it("prompt growth from this round stays under 3 percent on every version", () => {
    const BASE: Record<string, number> = { "1.21.1": 55554, "1.21.4": 56565, "1.21.8": 56795, "1.21.11": 58670 }; // chars before the instanced facts + rule
    for (const v of versions) {
      const n = PR.systemPrompt(v).length;
      assert.ok(n > BASE[v] - 2500, v);
      assert.ok(n <= BASE[v] * 1.03, `${v}: ${n} vs ${BASE[v]} = +${(((n - BASE[v]) / BASE[v]) * 100).toFixed(2)}%`);
    }
  });
  it("the failure rule is injected and the golden plugin is registered in the corpus", () => {
    assert.ok(PR.systemPrompt("1.21.11").includes("A world made for one run must be unloaded"));
    const gp = "services/modbuilder/golden/plugins/mc-instanced-dungeon-lite";
    const java = read(`${gp}/src/dev/nxeon/golden/dungeon/Dungeon.java`);
    for (const must of ["new WorldCreator(", "extends ChunkGenerator", "unloadWorld(", "getContents()", "setKeepInventory(true)", "BossBar.bossBar(", "deleteTree"]) assert.ok(java.includes(must), must);
    assert.equal(JSON.parse(read(`${gp}/golden.json`)).archetype, "dungeon_crawler");
    const res = JSON.parse(read("services/modbuilder/golden/results.json")) as { rows: { id: string; compile: Record<string, string>; scan: Record<string, string>; boot: Record<string, string> }[] };
    const row = res.rows.find((r) => r.id === "mc-instanced-dungeon-lite")!;
    for (const v of versions) { assert.equal(row.compile[v], "pass"); assert.equal(row.scan[v], "pass"); }
    assert.equal(row.boot["1.21.11"], "pass");
    const cov = JSON.parse(read("lib/cyrus/adapters/minecraft-coverage.json")) as { archetypes: { id: string; golden?: string }[] };
    assert.equal(cov.archetypes.find((a) => a.id === "dungeon_crawler")?.golden, "mc-instanced-dungeon-lite");
  });
});

